import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Perché la distribuzione di Poisson","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/le/leafca.md","filePath":"lezioni/l_calcolo-delle-probabilita/le/leafca.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/le/leafca.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="perche-la-distribuzione-di-poisson" tabindex="-1">Perché la distribuzione di Poisson <a class="header-anchor" href="#perche-la-distribuzione-di-poisson" aria-label="Permalink to “Perché la distribuzione di Poisson”">​</a></h1><p>Se consideriamo le probabilità di un evento che capita molto raramente, utilizzando la distribuzione binomiale (di Bernoulli), dovremo fare un numero enorme di calcoli considerando la probabilità dell&#39;evento e la probabilità contraria; la distribuzione di Poisson ci permette invece di calcolare tale probabilità con un&#39;ottima approssimazione senza dover fare eccessivi calcoli.</p><p>L&#39;importante per poter utilizzare la distribuzione di Poisson è il fatto che la probabilità dell&#39;accadere dell&#39;evento sia minuscola e sia molto elevato il numero dei dati considerati come universo: come orientamento pratico possiamo grosso modo dire che la distribuzione di Poisson è una buona approssimazione se il numero di casi possibili è superiore a <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100</mn></mrow><annotation encoding="application/x-tex">100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">100</span></span></span></span> e la probabilità dell&#39;accadere dell&#39;evento considerato è minore di almeno <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mn>10</mn></mrow><annotation encoding="application/x-tex">1/10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/10</span></span></span></span>.</p><blockquote><p>Mi ricordo che quando insegnavo, l&#39;esempio classico da cui partivo (e che penso sia stato usato da Poisson) era sul numero di soldati di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10</mn></mrow><annotation encoding="application/x-tex">10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> reggimenti prussiani morti per il calcio di un mulo ogni anno per <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>20</mn></mrow><annotation encoding="application/x-tex">20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">20</span></span></span></span> anni: la frequenza dell&#39;evento coincide in pratica con il valore della probabilità dato dalla distribuzione di Poisson: nelle pagine seguenti riporto il calcolo delle varie probabilità confrontato con le frequenze effettivamente ottenute.</p></blockquote>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};